                        var swipe2 = [shishen_icon.x + 60, shishen_icon.y - 240, shishen_icon.x + 80, shishen_icon.y - 220, 1000];
                        thisScript.regionBezierSwipe(swipe1, swipe2, [800, 1000], 0, 1000);
