        /**
         * 生成与当前时间戳相关的随机数字字符串
         * @param length 要生成的字符串长度（建议5-8位）
         * @returns 指定长度的数字字符串
         */
        function generateRandomNumberString(length) {
            var _a;
            // 获取当前时间戳的最后6位
            var timestamp = Date.now() % 1000000;
            // 生成3个独立的随机数
            var random1 = Math.floor(Math.random() * 1000);
            var random2 = Math.floor(Math.random() * 1000);
            var random3 = Math.floor(Math.random() * 100);
            // 组合多个随机源
            var parts = [
                timestamp.toString().slice(-3),
                random1.toString().padStart(3, '0'),
                random2.toString().padStart(3, '0'),
                random3.toString().padStart(2, '0'), // 随机数3，2位
            ];
            // 打乱数组顺序
            for (var i = parts.length - 1; i > 0; i--) {
                var j = Math.floor(Math.random() * (i + 1));
                _a = [parts[j], parts[i]], parts[i] = _a[0], parts[j] = _a[1];
            }
            // 合并所有部分
            var combined = parts.join('');
            // 再次打乱字符顺序
            var shuffled = combined.split('')
                .sort(function () { return Math.random() - 0.5; })
                .join('');
            // 截取所需长度
            return shuffled.slice(0, length);
        }
