        /**
         * 阴门挑战
         */
        function do_yinmen() {
            var taskName = '阴门挑战';
            var thisOperator = thisScript.formatOperate(_taskConfig__WEBPACK_IMPORTED_MODULE_0__["default"][taskName], taskName);
            if (thisScript.oper({
                name: '检测_阴门',
                operator: [{
                        desc: thisOperator[0].desc
                    }]
            })) {
                if (thisScript.runtimeParams && thisScript.runtimeParams.liao_activity_state) {
                    if (thisScript.runtimeParams.liao_activity_state['gateOfHades']) {
                        thisScript.oper({
                            name: '检测_退出阴门',
                            operator: [{
                                    oper: [thisOperator[0].oper[1]]
                                }]
                        });
                        sleep(1200);
                        thisScript.global.taskIndex++;
                    }
                    else {
                        return thisScript.oper({
                            name: '检测_进入阴门挑战',
                            operator: [{
                                    oper: [thisOperator[0].oper[0]]
                                }]
                        });
                    }
                }
                else {
                    if (thisScript.global.gateOfHades_state) {
                        thisScript.oper({
                            name: '检测_退出阴门',
                            operator: [{
                                    oper: [thisOperator[0].oper[1]]
                                }]
                        });
                        sleep(1200);
                        thisScript.global.taskIndex++;
                    }
                    else {
                        return thisScript.oper({
                            name: '检测_进入阴门挑战',
                            operator: [{
                                    oper: [thisOperator[0].oper[0]]
                                }]
                        });
                    }
                }
                return false;
            }
            if (thisScript.oper({
                name: '从组队界面挑战',
                operator: [thisOperator[4]]
            })) {
                return true;
            }
            if (thisScript.oper({
                name: '检测_阴门挑战弹窗界面',
                operator: [thisOperator[1]]
            })) {
                return true;
            }
            if (thisScript.oper({
                name: '检测_是否为36轮挑战弹窗',
                operator: [thisOperator[2]]
            })) {
                return true;
            }
            if (thisScript.oper({
                name: '检测_已完成挑战弹窗',
                operator: [thisOperator[3]]
            })) {
                if (thisScript.runtimeParams && thisScript.runtimeParams.liao_activity_state) {
                    thisScript.runtimeParams.liao_activity_state['gateOfHades'] = true;
                }
                thisScript.global.gateOfHades_state = true;
            }
            return false;
        }
        function go_liao_activity() {
            var taskName = '进入寮活动';
            var thisOperator = thisScript.formatOperate(_taskConfig__WEBPACK_IMPORTED_MODULE_0__["default"][taskName], taskName);
            var _liao_activity_state = thisScript.runtimeParams ? thisScript.runtimeParams.liao_activity_state : undefined;
            if (_liao_activity_state) {
                var _finishFlag_1 = true;
                //	若有一项未完成, 继续循环，否则返回庭院
                Object.keys(_liao_activity_state).forEach(function (key) {
                    if (!_liao_activity_state[key]) {
                        _finishFlag_1 = false;
                    }
                });
                console.log('寮活动当前状况为: ', _liao_activity_state, '返回庭院flag状态为: ', _finishFlag_1);
                if (_finishFlag_1) {
                    thisScript.global.taskIndex++;
                }
            }
            else {
            }
            if (thisScript.oper({
                name: '检测_狩猎战是否已开启',
                operator: [{
                        desc: thisOperator[4].desc
                    }]
            })) {
                if (thisconf.gateOfHades_switch) {
                    if (_liao_activity_state) {
                        var nowDateDay = new Date().getDay();
                        console.log('今天是周', nowDateDay);
                        switch (nowDateDay) {
                            case 5:
                            case 0:
                                {
                                    if (!(_liao_activity_state.narrow && _liao_activity_state.banquet)) {
                                        return false;
                                    }
                                    break;
                                }
                                ;
                            case 6: {
                                if (!(_liao_activity_state.narrow && _liao_activity_state.huntBoss)) {
                                    return false;
                                }
                                break;
                            }
                        }
                    }
                    if (_liao_activity_state && _liao_activity_state.hunt) {
                        return true;
                    }
                    else {
                        return thisScript.oper({
                            name: '检测_狩猎战是否已开启',
                            operator: [{
                                    oper: thisOperator[4].oper
                                }]
                        });
                    }
                }
            }
            if (thisScript.oper({
                name: '检测_狩猎战集结点',
                operator: [{
                        desc: thisOperator[5].desc,
                        oper: thisOperator[5].oper
                    }]
            })) {
                return true;
            }
            if (thisScript.oper({
                name: '检测_是否为挑战奉献榜场景_待开始',
                operator: [{
                        desc: thisOperator[7].desc,
                    }]
            })) {
                sleep(2000);
                thisScript.global.liao_activity_page_flag = 0;
                return true;
                // const next_scheme = '狩猎战';
                // thisScript.rerun(next_scheme, {
                //     liao_activity_state: _liao_activity_state
                // });
            }
            if (thisScript.oper({
                name: '检测_是否为阴门页面',
                operator: [thisOperator[10]]
            })) {
                sleep(2000);
                thisScript.global.liao_activity_page_flag = 0;
                return true;
                // const next_scheme = '阴门挑战';
                // thisScript.rerun(next_scheme, {
                //     liao_activity_state: _liao_activity_state
                // });
            }
            //	做延时识别
            if (thisScript.global.checked_yard_count > 5) {
                thisScript.global.checked_yard_count = 0;
                thisScript.global.liao_activity_page_flag += 1;
                return false;
            }
            else {
                sleep(500);
                if (!thisScript.global.checked_yard_count) {
                    thisScript.global.checked_yard_count = 1;
                }
                else {
                    thisScript.global.checked_yard_count += 1;
                }
                return true;
            }
        }
        /**
         * 阴门_准备
         */
        function yinmen_prepare(conf, zhenrong) {
            if (zhenrong === void 0) { zhenrong = null; }
            console.log('准备');
            thisScript.keepScreen(true);
            var taskName = '准备';
            var thisOperator = thisScript.formatOperate(_taskConfig__WEBPACK_IMPORTED_MODULE_0__["default"][taskName], taskName);
            sleep(1000);
            if (zhenrong && !(thisScript.global.war_change_shikigami_state === 'finish')) {
                if (thisScript.oper({
                    id: 1,
                    name: '准备界面_退出',
                    operator: [{
                            desc: '准备界面_未准备',
                        }]
                })) {
                    if (!thisScript.oper({
                        name: '战斗式神录 预设 侧栏',
                        operator: [{
                                desc: thisOperator[2].desc
                            }]
                    }) && thisScript.global.zhenrongSet) {
                        sleep(1000);
                        thisScript.global.war_yushe_find_count++;
                        if (thisScript.global.war_yushe_find_count > 5) {
                            thisScript.global.war_change_shikigami_state = 'finish';
                            thisScript.global.war_yushe_find_count = 0;
                        }
                        return false;
                    }
                    else {
                        thisScript.global.war_yushe_find_count = 0;
                    }
                    thisScript.global.zhenrongSet = false;
                    war_find_yushe(zhenrong);
                    war_page_yushe();
                    return false;
                }
            }
            else if (thisScript.global.war_change_shikigami_state === 'finish') {
                thisScript.global.zhenrongSet = true;
            }
            else if (!zhenrong) {
                thisScript.global.zhenrongSet = true;
            }
            if (thisScript.global.zhenrongSet) {
                console.log('开始识别准备界面');
                if (conf.exitBeforeReady) {
                    return thisScript.oper({
                        id: 1,
                        name: '准备界面_退出',
                        operator: [{
                                desc: '准备界面_未准备',
                                oper: [thisOperator[0].oper[1], thisOperator[0].oper[2]]
                            }]
                    }, 0);
                }
                else {
                    if (thisScript.oper({
                        id: 1,
                        name: '准备',
                        operator: [{
                                desc: '准备界面_未准备',
                            }]
                    }, 0)) {
                        if (!thisScript.global.yinmen_starting) {
                            if (thisScript.oper({
                                id: 1,
                                name: '准备',
                                operator: [{
                                        desc: '准备界面_未准备',
                                        oper: [thisOperator[0].oper[0]]
                                    }]
                            }, 0) || thisScript.oper({
                                id: 1,
                                name: '手动修正自动',
                                operator: [thisOperator[1]]
                            }, 1000)) {
                                thisScript.global.yinmen_starting = true;
                                // 每点一次准备 重置一次红标状态
                                if (thisScript.global.redFlag) {
                                    thisScript.global.redFlag = false;
                                }
                                sleep(2000);
                                return true;
                            }
                        }
                        else {
                            if (thisScript.oper({
                                id: 67,
                                name: '阴界退出',
                                operator: [thisOperator[3], thisOperator[4]]
                            })) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
