        /**
         * 保存图片
         * @param name
         */
        function saveImage(name) {
            var path = "/sdcard/Pictures/".concat(name, ".png");
            if (files.exists(path))
                return false;
            var bmp = thisScript.helperBridge.helper.GetBitmap();
            var img = com.stardust.autojs.core.image.ImageWrapper.ofBitmap(bmp);
            files.ensureDir(path);
            img.saveTo(path);
            bmp.recycle();
            img.recycle();
            sleep(2000);
        }
