        function getHuaHeReward() {
            var taskName = '领取花合战奖励';
            var thisOperator = thisScript.formatOperate(_taskConfig__WEBPACK_IMPORTED_MODULE_0__["default"][taskName], taskName);
            thisScript.oper({
                name: '花合战',
                operator: [thisOperator[0], thisOperator[2], thisOperator[8]
                ]
            });
            if ((!thisScript.oper({
                name: '查找花合战',
                operator: [{
                        desc: thisOperator[0].desc
                    }]
            }) && thisScript.oper({
                name: '查找花合战',
                operator: [thisOperator[6]]
            })) || thisScript.oper({
                name: '花合战_任务界面',
                operator: [{ desc: thisOperator[5].desc }]
            })) {
                if (thisScript.global.huahezhan && thisScript.oper({
                    name: '花合战_进入',
                    operator: [{
                            desc: thisOperator[6].desc,
                            oper: thisOperator[1].oper
                        }]
                })) {
                    return true;
                }
                if (thisScript.oper({
                    name: '花合战_任务界面',
                    operator: [{ desc: thisOperator[5].desc }]
                })) {
                    if (thisScript.oper({
                        name: '花合战_领取奖励',
                        operator: [thisOperator[3]]
                    })) {
                        thisScript.global.taskIndex++;
                        return true;
                    }
                    else {
                        //退出
                        thisScript.regionClick(thisOperator[5].oper);
                        thisScript.global.huahezhan = false;
                        thisScript.global.taskIndex++;
                        return true;
                    }
                }
            }
            else {
                var TextMatchMod = '包含';
                var Text_10 = '空白处关闭';
                var result = thisScript.findTextWithCompareColor(Text_10, 3000, thisOperator[7].oper[0], TextMatchMod, null);
                if (result.length === 0) {
                    thisScript.myToast("\u672A\u627E\u5230".concat(Text_10));
                }
                else {
                    var x = (result[0].points[0].x + result[0].points[1].x) / 2;
                    var y = (result[0].points[0].y + result[0].points[3].y) / 2;
                    var toClick = [
                        x + 300,
                        y - 400,
                        x + 400,
                        y + 30,
                        1000
                    ];
                    sleep(1000);
                    thisScript.regionClick([toClick]);
                    return true;
                }
            }
            return false;
        }
