// 添加一个通用的doPushWithRetry方法
function doPushWithRetry(thisScript, options) {
    var maxRetries = options.maxRetries || 6;
    var retryDelay = options.retryDelay || 10000;
    var retryCount = 0;
    while (retryCount < maxRetries) {
        try {
            var res = thisScript.doPush(thisScript, {
                text: options.text,
                message: options.message,
                before: options.before || (function () { })
            });
            // 检查返回结果是否有效
            if (res && (!options.message.type || res.accounts)) {
                if (retryCount > 0) {
                    thisScript.myToast('请求恢复');
                }
                return res;
            }
            continue;
        }
        catch (error) {
            retryCount++;
            thisScript.myToast("\u8BF7\u6C42\u5931\u8D25\uFF0C\u7B2C".concat(retryCount, "\u6B21\u91CD\u8BD5"));
            if (retryCount >= maxRetries) {
                thisScript.myToast('请求失败次数过多，停止脚本');
                thisScript.stop();
                return false;
            }
            sleep(retryDelay);
        }
    }
    return false;
}
