        /**
         * 判断是否在地鬼时间内
         */
        function judgeDiGuiTime() {
            var now = new Date();
            var currentTime = now.getHours() * 60 + now.getMinutes();
            var startTime = 6 * 60 + 10; // 6:10
            var endTime = 23 * 60 + 50; // 23:50
            if (!(currentTime >= startTime && currentTime <= endTime)) {
                if (!thisScript.global.diGuiDoing) { //在地鬼未开始时跳过
                    thisScript.global.taskIndex++;
                    thisScript.myToast('当前时间不在地鬼时间范围内');
                    return false;
                }
            }
            return true;
        }
