            var priorty2 = ['萤火之光', '妖力化身']; // 达到目标后的优先级
            var toClick = null;
            var type = null;
            var overCnt_1 = 0;
            priorty.forEach(function (item) {
                if (thisScript.global.d6d[item][0] >= thisScript.global.d6d[item][1]) {
                    overCnt_1++;
                }
            });
