    Func518.prototype.operatorFunc = function (thisScript, thisOperator) {
        if (thisScript.oper({
            id: 518,
            name: '页面是否为庭院',
            operator: [
                {
                    desc: thisOperator[0].desc,
                    oper: [thisOperator[0].oper[0]],
                },
                {
                    desc: thisOperator[1].desc,
                },
                {
                    desc: thisOperator[2].desc,
                },
                {
                    desc: thisOperator[3].desc,
                },
            ],
        })) {
            if (thisScript.global.daily_collection === 'friend') {
                return thisScript.oper({
                    id: 518,
                    name: '点击_好友',
                    operator: [
                        {
                            oper: [thisOperator[0].oper[1]],
                        },
                    ],
                });
            }
            if (thisScript.global.daily_collection === 'store') {
                return thisScript.oper({
                    id: 518,
                    name: '点击_商店',
                    operator: [
                        {
                            oper: [thisOperator[0].oper[2]],
                        },
                    ],
                });
            }
            if (thisScript.global.checked_yard_count < 3) {
                if (thisScript.oper({
                    id: 518,
                    name: '检测_是否有邮件',
                    operator: [thisOperator[4]],
                })) {
                    return true;
                }
            }
            return thisScript.oper({
                id: 518,
                name: '检测_是否有邮件或签到',
                operator: [
                    thisOperator[9],
                    thisOperator[13],
                    thisOperator[16],
                    thisOperator[18],
                    thisOperator[20],
                    thisOperator[21],
                    thisOperator[22],
                ],
            });
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_商店_礼包屋',
            operator: [
                {
                    desc: thisOperator[33].desc,
                },
            ],
        }) &&
            thisScript.global.daily_collection !== 'store') {
            return thisScript.oper({
                id: 518,
                name: '返回庭院',
                operator: [
                    {
                        oper: thisOperator[33].oper,
                    },
                ],
            });
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_领取奖励弹窗',
            operator: [
                thisOperator[5],
                thisOperator[7],
                thisOperator[8],
                thisOperator[9],
                thisOperator[10],
                thisOperator[11],
            ],
        })) {
            return true;
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_御魂是否满了',
            operator: [thisOperator[23]],
        })) {
            thisScript.global.checked_yard_count = 4;
            thisScript.doPush(thisScript, {
                text: '御魂已满，无法收取邮件奖励',
                before: function () {
                    thisScript.myToast('正在上传数据');
                },
            });
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_领取全部奖励弹窗',
            operator: [
                {
                    desc: thisOperator[6].desc,
                },
            ],
        })) {
            //	超过3次领取失败 判断为御魂满了
            if (thisScript.global.checked_yard_count > 3) {
                return thisScript.oper({
                    id: 518,
                    name: '关闭弹窗',
                    operator: [
                        {
                            oper: [thisOperator[5].oper[1]],
                        },
                    ],
                });
            }
            else {
                if (!thisScript.global.checked_yard_count) {
                    thisScript.global.checked_yard_count = 1;
                }
                else {
                    thisScript.global.checked_yard_count += 1;
                }
                return thisScript.oper({
                    id: 518,
                    name: '检测_领取全部奖励弹窗',
                    operator: [
                        {
                            oper: thisOperator[6].oper,
                        },
                    ],
                });
            }
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_签到_每日奖励_寮包',
            operator: [
                thisOperator[10],
                thisOperator[11],
                thisOperator[12],
                thisOperator[14],
                thisOperator[15],
                thisOperator[17],
                thisOperator[19],
                thisOperator[24],
                thisOperator[25],
                thisOperator[27],
                thisOperator[28],
                thisOperator[29],
                thisOperator[30],
                thisOperator[31],
                thisOperator[34],
                thisOperator[35],
                thisOperator[37],
                thisOperator[38], //  检测是否为好友弹窗 页签处于最近
            ],
        })) {
            return true;
        }
        if (thisScript.oper({
            id: 518,
            name: '友情点已领取',
            operator: [
                thisOperator[26], //  友情点已领取 关闭弹窗
            ],
        })) {
            thisScript.global.daily_collection = 'store';
            return true;
        }
        if (thisScript.oper({
            id: 518,
            name: '检测_商店_礼包屋_推荐页签',
            operator: [thisOperator[32]],
        })) {
            //  若3次找不到每日领取，直接视为已领取
            if (thisScript.oper({
                id: 518,
                name: '检测_商店_推荐页签_每日领取',
                operator: [thisOperator[36]],
            }) ||
                thisScript.global.checked_yard_count >= 3) {
                thisScript.global.checked_yard_count = 0;
                thisScript.global.daily_collection = 'courtyard';
            }
            if (!thisScript.global.checked_yard_count) {
                thisScript.global.checked_yard_count = 1;
            }
            else {
                thisScript.global.checked_yard_count += 1;
            }
            sleep(1000);
            return true;
        }
        return false;
    };
